		ROUNDUP: ROUNDUP,
		ROW: ROW,
		ROWS: ROWS,
		RRI: RRI,
		RSQ: RSQ,
		SEARCH: SEARCH,
		SEC: SEC,
		SECH: SECH,
		SECOND: SECOND,
		SERIESSUM: SERIESSUM,
		SIGN: SIGN,
		SIN: SIN,
		SINH: SINH,
		SKEW: SKEW,
		SKEWP: SKEWP,
		SLN: SLN,
		SLOPE: SLOPE,
		SMALL: SMALL,
		SORT: SORT,
		SQRT: SQRT,
		SQRTPI: SQRTPI,
		STANDARDIZE: STANDARDIZE,
		STDEV: STDEV,
		STDEVA: STDEVA,
		STDEVP: STDEVP,
		STDEVPA: STDEVPA,
		STDEVS: STDEVS,
		STEYX: STEYX,
		SUBSTITUTE: SUBSTITUTE,
		SUBTOTAL: SUBTOTAL,
		SUM: SUM,
		SUMIF: SUMIF,
		SUMIFS: SUMIFS,
		SUMPRODUCT: SUMPRODUCT,
		SUMSQ: SUMSQ,
		SUMX2MY2: SUMX2MY2,
		SUMX2PY2: SUMX2PY2,
		SUMXMY2: SUMXMY2,
		SWITCH: SWITCH,
		SYD: SYD,
		T: T,
		TAKE: TAKE,
		TAN: TAN,
		TANH: TANH,
		TBILLEQ: TBILLEQ,
		TBILLPRICE: TBILLPRICE,
		TBILLYIELD: TBILLYIELD,
		TDIST: TDIST,
		TDISTRT: TDISTRT,
		TEXT: TEXT,
		TEXTJOIN: TEXTJOIN,
		TIME: TIME,
		TIMEVALUE: TIMEVALUE,
		TINV: TINV,
		TODAY: TODAY,
		TRANSPOSE: TRANSPOSE,
		TREND: TREND,
		TRIM: TRIM,
		TRIMMEAN: TRIMMEAN,
		TRUE: TRUE,
		TRUNC: TRUNC,
		TTEST: TTEST,
		TYPE: TYPE,
		UNICHAR: UNICHAR,
		UNICODE: UNICODE,
		UNIQUE: UNIQUE,
		UPPER: UPPER,
